using Eternities.Data;
using Eternities.Kits;
using Eternities.Layout;
using NUnit.Framework;
using UnityEngine;

namespace Eternities.Tests
{
    // PRD v4 8.4.5 and 9.5: the ground is generated by the kit's noise with the seed, and is flat
    // under the plaza, the paths, the pads, the aprons and the corridors; one river and one lake lie
    // in the kit's water zone.
    public class GroundTests
    {
        static WorldLayout layout;
        static GroundPlan plan;

        [OneTimeSetUp]
        public void PlanDominaria()
        {
            var pack = new Pack(TestPack.Directory);
            PackPlane plane = pack.Plane("dominaria");
            layout = Allocator.Run(LayoutInputs.From(plane, pack.Cards(plane)));
            plan = GroundPlan.Compute(layout);
        }

        [Test]
        public void TheGroundIsFlatUnderEverythingTheAllocatorPlaced()
        {
            Assert.That(plan.HeightResolution, Is.EqualTo(2049));
            Assert.That(plan.HeightAt(0, 0), Is.EqualTo(0), "the plaza");
            foreach (LayoutStand stand in layout.Stands)
            {
                Vector3 at = StandField.Ground(stand.Position), ahead = StandField.Facing(stand) * Vector3.forward;
                Vector3 end = StandField.Ground(stand.PathPoint);
                Assert.That(plan.HeightAt(at.x, at.z), Is.EqualTo(0), "a stand's footprint");
                Assert.That(plan.HeightAt(at.x + ahead.x, at.z + ahead.z), Is.EqualTo(0), "its apron");
                Assert.That(plan.HeightAt((at.x + end.x) / 2, (at.z + end.z) / 2), Is.EqualTo(0), "its corridor");
                Assert.That(plan.HeightAt(end.x, end.z), Is.EqualTo(0), "the path its corridor ends on");
            }
            foreach (LayoutPad pad in layout.Pads)
            {
                Vector3 at = StandField.Ground(pad.Centre);
                Assert.That(plan.HeightAt(at.x, at.z), Is.EqualTo(0), "a pad");
            }
        }

        [Test]
        public void TheReliefIsTheKitsHillsAndTheSameEveryTime()
        {
            float highest = 0, lowest = 0;
            foreach (float height in plan.Heights)
            {
                highest = Mathf.Max(highest, height);
                lowest = Mathf.Min(lowest, height);
            }
            Assert.That(highest, Is.InRange(1.5f, 3f), "hills of up to 3 m");
            Assert.That(lowest, Is.EqualTo(-GroundPlan.LakeDepth).Within(0.05f), "nothing is lower than the lake's bed");
            // How much of the world itself has relief: little, because a band is 6 m wide and the
            // ground is flat under every corridor in it. The hills are in the margin.
            int inside = 0, raised = 0;
            float texel = plan.Side / plan.AlphaResolution, radius = layout.WorldRadius / 1000f;
            for (int row = 0; row < plan.HeightResolution; row++)
            {
                for (int column = 0; column < plan.HeightResolution; column++)
                {
                    float x = -plan.Side / 2 + column * texel, z = -plan.Side / 2 + row * texel;
                    if (x * x + z * z < radius * radius)
                    {
                        inside++;
                        raised += plan.Heights[row, column] > 0.25f ? 1 : 0;
                    }
                }
            }
            Debug.Log($"GroundTests: {100f * raised / inside:F1}% of Dominaria's ground inside the rim rises more than 0.25 m");
            Assert.That(raised, Is.GreaterThan(0));
            GroundPlan again = GroundPlan.Compute(layout);
            Assert.That(again.Heights, Is.EqualTo(plan.Heights));
            GroundPlan steeper = GroundPlan.Compute(layout, hillHeight: 6, hillWidth: 30);
            Assert.That(steeper.Heights, Is.Not.EqualTo(plan.Heights));
            Assert.That(steeper.HeightAt(0, 0), Is.EqualTo(0));
        }

        [Test]
        public void TheRiverAndTheLakeLieBeyondTheRingWithGravelBanks()
        {
            float radius = layout.WorldRadius / 1000f;
            Vector2 mid = (plan.RiverFrom + plan.RiverTo) / 2;
            Assert.That(mid.y - GroundPlan.RiverHalfWidth - GroundPlan.Bank, Is.GreaterThan(radius + 3), "the river's bank is past the 3 m buffer of the rim");
            Assert.That(plan.HeightAt(mid.x, mid.y), Is.LessThan(GroundPlan.WaterLevel - 0.5f), "the river's bed is under water");
            Assert.That(plan.HeightAt(plan.LakeCentre.x, plan.LakeCentre.y), Is.EqualTo(-GroundPlan.LakeDepth).Within(0.01f));
            Assert.That(plan.Wet(mid.x, mid.y));
            Assert.That(plan.Wet(0, radius), Is.False, "the end of the north radial path is dry");
            float reach = GroundPlan.LakeRadius + GroundPlan.Bank;
            Assert.That(Mathf.Max(Mathf.Abs(plan.LakeCentre.x), Mathf.Abs(plan.LakeCentre.y)) + reach, Is.LessThan(plan.Side / 2), "the lake is on the terrain");
            Assert.That(plan.LakeCentre.magnitude - reach, Is.GreaterThan(radius + 3), "the lake's shore is past the 3 m buffer of the rim");

            int n = plan.AlphaResolution;
            float texel = plan.Side / n;
            int Row(float z) => Mathf.FloorToInt((z + plan.Side / 2) / texel);
            Assert.That(plan.Alphas[Row(mid.y), Row(mid.x), GroundPlan.Gravel], Is.EqualTo(1));
            Assert.That(plan.Alphas[Row(0), Row(0), GroundPlan.Path], Is.EqualTo(1));
        }
    }
}
